listRule:
// A leaf node authenticating as itself sees only its own record.
// A user sees all leaf nodes belonging to their active organization.
// Sentinel guard: in PocketBase an empty string equals an empty string, so a
// blank organization must never scope a read. Do not put an apostrophe in a
// rule comment: quotes are tokenized before comments are stripped, so one
// stray apostrophe re-pairs every quote after it and the rule stops parsing.
// See migrations/schema_update_tenancy_sentinel.go.
(@request.auth.collectionName = "leaf_nodes" && id = @request.auth.id) || 
(@request.auth.collectionName = "users" && @request.auth.current_organization != "" && organization = @request.auth.current_organization && @request.auth.memberships_via_user.organization ?= @request.auth.current_organization)

viewRule:
// A leaf node authenticating as itself sees only its own record.
// A user sees all leaf nodes belonging to their active organization.
// Sentinel guard: in PocketBase an empty string equals an empty string, so a
// blank organization must never scope a read. Do not put an apostrophe in a
// rule comment: quotes are tokenized before comments are stripped, so one
// stray apostrophe re-pairs every quote after it and the rule stops parsing.
// See migrations/schema_update_tenancy_sentinel.go.
(@request.auth.collectionName = "leaf_nodes" && id = @request.auth.id) || 
(@request.auth.collectionName = "users" && @request.auth.current_organization != "" && organization = @request.auth.current_organization && @request.auth.memberships_via_user.organization ?= @request.auth.current_organization)

createRule:
// Only Admins or Owners can create leaf nodes for their active organization.
@request.auth.collectionName = "users" && 
@request.body.organization = @request.auth.current_organization && 
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization && 
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))

updateRule:
// 1. Must be Admin/Owner.
// 2. Must belong to active org.
// 3. Prevent organization field tampering.
// 4. Freeze `code`: it is the KV key prefix and the JetStream domain suffix,
//    so changing it silently orphans everything the edge already wrote.
organization = @request.auth.current_organization && 
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization && 
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin")) && 
@request.body.organization:changed = false &&
@request.body.code:changed = false

authRule:
// A deactivated leaf node cannot obtain a new auth token, so leaf-sync stops
// pulling config and GET /api/leaf/bootstrap stops answering it.
//
// Same caveat and same remedy as the things authRule: this is checked at the
// auth endpoint only, and hooks/active_flag.go refreshes tokenKey and revokes
// the linked NATS identity on deactivation so the edge box actually goes dark.
// leaf_nodes has no member-level write path -- create/update are already
// owner/admin -- so `active` needs no extra field freeze.
active = true
